  ('sport-0014', 'sport', 'open', 1, 'review', 'hks/sportskih-100-kiric#40', 'Wikipedia (en): 1998 FIFA World Cup knockout stage', array['nogomet', 'hrvatska reprezentacija']::text[], false, '2026-10-05'::date, 'Izvorno pitanje (2021.) tvrdi da su osim Hrvatske samo Portugalci dobili sva svoja četvrtfinala SP-a. To više ne vrijedi jer je Portugal 2022. izgubio četvrtfinale od Maroka, pa je pitanje zamijenjeno stabilnom činjenicom.'),
  ('sport-0015', 'sport', 'estimate', 3, 'review', 'hks/sportskih-100-kiric#37', 'Wikipedia (en): Volleyball', array['odbojka', 'pravila']::text[], false, '2026-10-05'::date, 'Pretvoreno u pitanje procjene.'),
  ('sport-0016', 'sport', 'estimate', 2, 'review', 'hks/sportskih-100-kiric#98', 'Wikipedia (en): Ironman Triathlon', array['triatlon']::text[], false, '2026-10-05'::date, 'U izvornom pitanju maraton je naveden kao „42 195 km”; ispravljeno.'),
