  ('sport-0018', 'sport', 'true_false', 2, 'review', 'hks/sportskih-100-kiric#15', 'Wikipedia (en): Canada at the 1976 Summer Olympics', array['olimpijske igre']::text[], false, '2026-10-05'::date, 'Pretvoreno u točno/netočno.'),
  ('sport-0019', 'sport', 'open', 3, 'review', 'hks/sportskih-100-kiric#82', 'Wikipedia (en): 1992 Winter Olympics', array['olimpijske igre', 'nogomet']::text[], false, '2026-10-05'::date, null),
