  ('sport-0021', 'sport', 'open', 2, 'review', 'hks/sportskih-100-kiric#36', 'Wikipedia (en): Croatia Davis Cup team', array['tenis', 'hrvatska reprezentacija']::text[], false, '2026-10-05'::date, null),
  ('sport-0022', 'sport', 'open', 2, 'review', 'hks/sportskih-100-kiric#4', 'Wikipedia (en): George Best Belfast City Airport', array['nogomet']::text[], false, '2026-10-05'::date, null),
  ('sport-0023', 'sport', 'open', 2, 'review', 'hks/sportskih-100-kiric#10', 'Wikipedia (en): Greco-Roman wrestling', array['hrvanje', 'pravila']::text[], false, '2026-10-05'::date, null),
  ('sport-0024', 'sport', 'open', 2, 'review', 'hks/sportskih-100-kiric#39', 'Wikipedia (en): George Foreman', array['boks']::text[], false, '2026-10-05'::date, 'Izvorno pitanje navodi 46 godina. Foreman je rođen 10. siječnja 1949., a meč je bio 5. studenoga 1994., pa je imao 45.'),
  ('sport-0025', 'sport', 'true_false', 2, 'review', 'hks/sportskih-100-kiric#21', 'Wikipedia (en): Ligue 1', array['nogomet', 'rekordi']::text[], true, '2026-10-05'::date, 'Izvorno pitanje (2021.) daje Saint-Étienne kao točan odgovor; od 2023. to više ne vrijedi. Pretvoreno u točno/netočno.'),
  ('sport-0026', 'sport', 'open', 3, 'review', 'hks/sportskih-100-kiric#34', 'Wikipedia (en): Emanuel Lasker', array['šah']::text[], false, '2026-10-05'::date, 'U ključu izvornog seta za ovo pitanje stoji „ŠAH”, što je greška. Šah je po pravilniku kategorija svrstan u Sport.'),
