insert into public.question_texts (question_id, question, answer, accept, note)
values
  ('culture-0001', 'Koji je talijanski renesansni umjetnik naslikao Mona Lisu?', 'Leonardo da Vinci', array['Leonardo']::text[], 'Slika je 1911. ukradena iz Louvrea, a vraćena je tek 1914.'),
  ('culture-0002', 'Koji je nizozemski slikar 1889. naslikao „Zvjezdanu noć”?', 'Vincent van Gogh', array['Van Gogh']::text[], 'Prikazao je pogled kroz istočni prozor svoje sobe u lječilištu u Saint-Rémy-de-Provenceu.'),
  ('culture-0003', 'Koji je junak grčke mitologije morao izvršiti dvanaest zadataka?', 'Heraklo', array['Herakle', 'Herkul', 'Heracles']::text[], 'Rimljani su ga zvali Herkul.'),
  ('culture-0004', 'Koji je hrvatski kipar 1929. izradio kip Grgura Ninskog u Splitu?', 'Ivan Meštrović', array['Meštrović']::text[], 'Njegov „Zdenac života” ispred zagrebačkog HNK nastao je 1905., pod utjecajem secesije i Rodina.'),
  ('culture-0005', 'Kako se zovu ukrasni kolači od medenog tijesta čija je izrada 2010. upisana na UNESCO-ov popis kao baština sjeverne Hrvatske?', 'Licitari', array['Licitar', 'Licitarsko srce']::text[], 'Tijesto se radi od meda, brašna, jaja, vode i prirodnih boja.'),
  ('culture-0006', 'Koji je arhitekt od 1883. do kraja života vodio gradnju barcelonske Sagrade Família?', 'Antoni Gaudí', array['Gaudí', 'Gaudi']::text[], 'Pokopan je u kripti te crkve.'),
  ('culture-0007', 'Kako se zove korčulanski ples s mačevima u kojem se Bijeli i Crni kralj bore za djevojku Bulu?', 'Moreška', '{}', 'Pobjeđuje Bijeli kralj, koji porazi crne vojnike i oslobodi Bulu.'),
  ('culture-0008', 'Koji je graditelj od 1441. do smrti vodio gradnju šibenske katedrale sv. Jakova?', 'Juraj Dalmatinac', array['Giorgio da Sebenico']::text[], 'Na vijencu apsida nalazi se više od 70 isklesanih ljudskih glava.'),
  ('culture-0009', 'Koji je mogulski car dao sagraditi Tadž Mahal u spomen na svoju suprugu?', 'Šah Džahan', array['Shah Jahan', 'Šahdžahan']::text[], 'Na gradnji je radilo više od 20 000 radnika i majstora.'),
  ('culture-0010', 'Koji se tradicijski ples iz dubrovačkog kraja pleše uz lijericu?', 'Linđo', array['Lindjo', 'Dubrovačka poskočica']::text[], 'Kolovođa duhovitim stihovima izvikuje naredbe i određuje koji parovi plešu.'),
  ('science_tech-0001', 'Pri kojoj temperaturi Celzijeva i Fahrenheitova ljestvica pokazuju isti broj?', '−40 °C', array['−40 °F', '-40']::text[], 'Na Fahrenheitovoj ljestvici voda se ledi na 32 °F, a vrije na 212 °F.'),
  ('sport-0001', 'Na kojoj je visini košarkaški obruč, u centimetrima?', '305 cm', '{}', 'To je točno 10 stopa; obruč je 122 cm odmaknut od crte iza koša.'),
  ('history-0001', 'Koje je godine car Leopold I. izdao povelju iz koje je nastalo Sveučilište u Zagrebu?', '1669.', array['1669']::text[], 'Povelja je bila za isusovačku akademiju, iz koje je kasnije izraslo sveučilište.'),
  ('geography-0001', 'Koliko je metara visoko Sljeme, najviši vrh Medvednice?', '1033 m', '{}', 'Na vrhu je 169 metara visok radiotelevizijski toranj iz 1973.'),
  ('nature-0001', 'Koliko trajnih zuba obično ima odrastao čovjek, računajući umnjake?', '32', '{}', 'Djeca imaju 20 mliječnih zuba.'),
  ('culture-0011', 'Koliko je metara visok Kip slobode, od tla do vrha baklje?', '93 m', '{}', 'Željeznu konstrukciju kipa projektirao je Gustave Eiffel.'),
  ('film_tv-0001', 'Koliko je Oscara osvojio film „Titanic” iz 1997.?', '11', '{}', 'Time je izjednačio rekord filma „Ben-Hur” iz 1959.'),
  ('language_literature-0001', 'Koliko stihova ima sonet?', '14', '{}', 'Oblik je nastao u 13. stoljeću na Siciliji, a začetnikom se smatra Giacomo da Lentini.'),
  ('general-0001', 'Koliko grama ima jedna unča?', '28,35 g', array['28,349523125 g']::text[], 'Šesnaest unci čini jednu funtu.'),
  ('music-0001', 'Koliko tipki ima standardni moderni klavir?', '88', '{}', 'Od toga su 52 bijele i 36 crnih tipki.'),
  ('film_tv-0002', 'Koja je animirana serija o kamenodobnom Fredu i njegovoj obitelji bila prva prikazivana u udarnom večernjem terminu američke televizije?', 'Kremenkovi', array['The Flintstones', 'Obitelj Kremenko', 'Porodica Kremenko']::text[], 'Seriju su stvorili William Hanna i Joseph Barbera, a prva je epizoda prikazana 1960.'),
  ('film_tv-0003', 'Koji je crtani film Dušana Vukotića 1962. postao prvi animirani film izvan SAD-a nagrađen Oscarom?', 'Surogat', array['Ersatz']::text[], 'Vukotić je bio jedan od začetnika prepoznatljivog stila Zagrebačke škole crtanog filma.'),
  ('film_tv-0004', 'U kojoj je seriji HBO-a Dubrovnik od druge sezone glumio prijestolnicu King’s Landing?', 'Igra prijestolja', array['Game of Thrones']::text[], 'U prvoj su sezoni te scene snimane u Mdini na Malti.'),
  ('film_tv-0005', 'Koji je redatelj 1975. snimio film „Ralje”?', 'Steven Spielberg', array['Spielberg']::text[], '„Ralje” se smatraju prototipom ljetnog blockbustera.'),
  ('film_tv-0006', 'Koji je glumac Oscara za najbolju mušku ulogu dobio za film „Povratnik”?', 'Leonardo DiCaprio', array['DiCaprio']::text[], 'Prvu nominaciju za Oscara dobio je s 19 godina, za film „Što muči Gilberta Grapea”.'),
  ('film_tv-0007', 'Kako se zove Nintendov vodoinstalater, brat Luigija?', 'Mario', array['Super Mario']::text[], 'U prvoj igri, „Donkey Kongu” iz 1981., zvao se Jumpman.'),
  ('film_tv-0008', 'Koji je ratni film iz 1927. dobio prvog Oscara za najbolji film?', 'Krila', array['Wings']::text[], 'Ostao je jedini potpuno nijemi film s Oscarom za najbolji film.'),
  ('film_tv-0009', 'Koja je dječja serija po romanima Hrvoja Hitreca pratila zagrebačku obitelj Vragec?', 'Smogovci', '{}', 'Obitelj živi u Peščenici, a serija se prikazivala od 1982. do 1997.'),
  ('film_tv-0010', 'Koji je prvi dugometražni film studija Pixar, iz 1995.?', 'Priča o igračkama', array['Toy Story']::text[], 'Bio je to prvi dugometražni film u potpunosti napravljen računalnom animacijom.'),
  ('film_tv-0011', 'Na kojem se filmskom festivalu dodjeljuje Zlatna palma?', 'Cannes', array['Filmski festival u Cannesu', 'Kan']::text[], 'Zlatna palma uvedena je 1955.; prije toga glavna nagrada zvala se Grand Prix.'),
  ('general-0002', 'Koja je mjerna jedinica za snagu dobila ime po škotskom inženjeru koji je usavršio parni stroj?', 'Vat', array['Watt', 'W']::text[], 'Jedna konjska snaga iznosi otprilike 746 vata.'),
  ('general-0003', 'Koja je talijanska kava dobila ime po boji odore redovnika kapucina?', 'Kapučino', array['Cappuccino']::text[], 'Ime ne dolazi od same kapuljače, nego od boje njihovih halja s kapuljačom.'),
  ('general-0004', 'Koji modni dodatak, čije ime potječe od imena Hrvata, ima svoj dan 18. listopada?', 'Kravata', '{}', 'Dan kravate Hrvatski sabor proglasio je 2008., na poticaj udruge Academia Cravatica.'),
  ('general-0005', 'Koja je hrvatska tvrtka 1959. počela proizvoditi začin Vegetu?', 'Podravka', '{}', 'Recept je osmislila Zlata Bartl, voditeljica tima u Podravkinu istraživačkom laboratoriju.'),
  ('general-0006', 'Koji znak iz adresa e-pošte Talijani zovu „chiocciola”, odnosno puž?', '@', array['et', 'majmunčić', 'manki']::text[], 'U hrvatskom ga kolokvijalno zovu i majmunčić ili manki, prema engleskoj riječi monkey.'),
  ('general-0007', 'Koje jelo od riže, obojeno šafranom, potječe iz Valencije?', 'Paella', array['Paelja']::text[], 'Ime je dobilo po širokoj plitkoj tavi u kojoj se tradicionalno kuha na otvorenoj vatri.'),
  ('general-0008', 'Koja je švedska tvrtka za namještaj dobila ime po inicijalima osnivača, njegove farme i obližnjeg sela?', 'IKEA', '{}', 'Ingvar Kamprad osnovao ju je 1943., sa samo 17 godina.'),
  ('general-0009', 'Koji standardni format papira ima dimenzije 210 × 297 mm?', 'A4', '{}', 'Format A0 ima površinu od otprilike jednog četvornog metra, a svaki sljedeći nastaje prepolovljavanjem prethodnog.'),
  ('general-0010', 'Koja je Kraševa praline od nugata s bademima i lješnjacima dobila ime po orijentalnoj plesačici?', 'Bajadera', '{}', 'Bila je prvi proizvod koji je dobio oznaku Izvorno hrvatsko.'),
  ('general-0011', 'Po kojem je američkom ljekarniku nazvana ljestvica za mjerenje ljutine papričica?', 'Wilbur Scoville', array['Scoville']::text[], 'Izvorni test iz 1912. razrjeđivao je ekstrakt papričice šećernom vodicom dok kušači više nisu osjećali ljutinu.'),
  ('geography-0002', 'Koja je najdulja rijeka u Hrvatskoj?', 'Sava', '{}', 'Izvire u Sloveniji, a u Dunav se ulijeva u Beogradu.'),
  ('geography-0003', 'Na kojoj se planini nalazi Sinjal, najviši vrh Hrvatske?', 'Dinara', '{}', 'Najviši vrh cijelog masiva, Troglav (1913 m), nalazi se u Bosni i Hercegovini.'),
  ('geography-0004', 'Koji je grad glavni grad Kanade?', 'Ottawa', '{}', 'Za glavni grad izabrala ju je britanska kraljica Viktorija 1857.'),
  ('geography-0005', 'Koje je najdublje jezero na svijetu?', 'Bajkalsko jezero', array['Bajkal']::text[], 'U njemu se nalazi oko petine sve nezaleđene slatke vode na Zemlji.'),
  ('geography-0006', 'Koja afrička država ima najviše stanovnika?', 'Nigerija', '{}', 'Najveći grad je Lagos, ali glavni je grad Abuja.'),
  ('geography-0007', 'Koja je najviša planina Afrike?', 'Kilimandžaro', array['Kilimanjaro']::text[], 'To je vulkan i najviša samostojeća planina na svijetu, koja ne pripada nijednom gorskom lancu.'),
  ('geography-0008', 'Koje se jezero, najveće u Hrvatskoj, nalazi sjeverozapadno od Pakoštana?', 'Vransko jezero', '{}', 'Zaštićeno je kao park prirode, s ornitološkim područjem važnim za ptice.'),
  ('geography-0009', 'Koja rijeka izvire u Plitvičkim jezerima, a u Kupu se ulijeva u Karlovcu?', 'Korana', '{}', 'Plitvička jezera najstariji su hrvatski nacionalni park, proglašen 1949.'),
  ('geography-0010', 'Koja je najveća država Južne Amerike?', 'Brazil', '{}', 'Graniči sa svim državama kontinenta osim Čilea i Ekvadora.'),
  ('geography-0011', 'Koja država ima jedinu nacionalnu zastavu koja nije pravokutna?', 'Nepal', '{}', 'To je ujedno jedina nacionalna zastava koja je viša nego što je široka.'),
  ('history-0002', 'Koje je godine Kristofor Kolumbo na svom prvom putovanju stigao do Amerike?', '1492.', array['1492']::text[], 'Isplovio je s tri broda: Santa María, Pinta i Niña.'),
  ('history-0003', 'Čiji se konjanički kip od 1866. nalazi na glavnom zagrebačkom trgu?', 'Josip Jelačić', array['Ban Jelačić', 'Jelačić']::text[], 'Kip je uklonjen 1947., a na trg je vraćen 1990.'),
  ('history-0004', 'Koji je rimski car u Splitu dao sagraditi palaču u koju se povukao nakon vladavine?', 'Dioklecijan', array['Diocletian']::text[], 'Prijestolja se odrekao 1. svibnja 305.'),
  ('history-0005', 'Koji je zid otvoren 9. studenoga 1989.?', 'Berlinski zid', array['Berlinski']::text[], 'Granica oko Zapadnog Berlina bila je duga oko 155 kilometara.'),
  ('history-0006', 'Čiju je gotovo netaknutu grobnicu 1922. pronašao Howard Carter?', 'Tutankamon', array['Tutankhamun', 'Tutankamonova']::text[], 'Faraon je postao kao dječak od osam ili devet godina.'),
  ('history-0007', 'Koji je hrvatski vladar oko 925. postao prvi hrvatski kralj?', 'Tomislav', array['Kralj Tomislav']::text[], 'Ne zna se točno kada, gdje ni tko ga je okrunio.'),
  ('history-0008', 'Koja je britanska kraljica vladala 63 godine, gotovo cijelu drugu polovicu 19. stoljeća?', 'Viktorija', array['Kraljica Viktorija', 'Victoria']::text[], 'Najdulje je vladala tek Elizabeta II., više od 70 godina.'),
  ('history-0009', 'Koji je mletački putnik opisao boravak u Kini, a prema jednoj teoriji rođen je na Korčuli?', 'Marko Polo', array['Marco Polo']::text[], 'Putopis je izdiktirao Rustichellu iz Pise dok je bio u genoveškom zatočeništvu.'),
  ('history-0010', 'Koji je bizantski car dao sagraditi Aju Sofiju u današnjem obliku?', 'Justinijan I.', array['Justinijan', 'Justinian']::text[], 'Gradnja je trajala manje od šest godina, od 532. do 537.'),
  ('history-0011', 'U kojoj je bitki 1066. normandijski vojvoda Vilim porazio engleskog kralja Harolda?', 'Bitka kod Hastingsa', array['Hastings']::text[], 'Bitka je prikazana na tapiseriji iz Bayeuxa, dugoj oko 70 metara.'),
  ('language_literature-0002', 'Koja je hrvatska književnica napisala „Čudnovate zgode šegrta Hlapića”?', 'Ivana Brlić-Mažuranić', array['Brlić-Mažuranić']::text[], 'Zbog njezinih bajki zvali su je hrvatskim Andersenom, ali i hrvatskim Tolkienom.'),
  ('language_literature-0003', 'Tko je napisao tragediju „Romeo i Julija”?', 'William Shakespeare', array['Shakespeare']::text[], 'Radnja se odvija u talijanskim gradovima Veroni i Mantovi.'),
  ('language_literature-0004', 'Koji je slavni detektiv živio u londonskoj ulici Baker Street 221B?', 'Sherlock Holmes', array['Holmes']::text[], 'Kad je Doyle 1893. objavio Holmesovu smrt, časopis Strand navodno je izgubio više od 20 000 pretplatnika.'),
  ('language_literature-0005', 'Koji je Asterixov prijatelj kao dijete upao u kotao s čarobnim napitkom?', 'Obelix', '{}', 'Zato je jedini u selu na kojeg napitak djeluje trajno, pa ga ne smije piti.'),
  ('language_literature-0006', 'Koji se glagoljski kameni spomenik iz oko 1100. naziva „krsnim listom” hrvatskog naroda?', 'Bašćanska ploča', '{}', 'Pronađena je 1851. u crkvi sv. Lucije u Jurandvoru na Krku.'),
  ('language_literature-0007', 'Koji je dubrovački barokni pjesnik napisao ep „Osman”?', 'Ivan Gundulić', array['Gundulić']::text[], 'Njegov portret bio je glavni motiv novčanice od 50 kuna.'),
  ('language_literature-0008', 'Koliko slova ima hrvatska abeceda?', '30', array['Trideset']::text[], 'Tri slova, dž, lj i nj, pišu se s dva znaka.'),
  ('language_literature-0009', 'Koji je kolumbijski pisac napisao roman „Sto godina samoće”?', 'Gabriel García Márquez', array['García Márquez', 'Márquez', 'Marquez']::text[], 'Radnja se odvija u izmišljenom gradiću Macondu.'),
  ('language_literature-0010', 'Kako se zove prva hrvatska tiskana knjiga, glagoljski misal iz 1483.?', 'Misal po zakonu rimskoga dvora', array['Prvotisak', 'Misal']::text[], 'Bio je prvi misal na svijetu koji nije tiskan latinicom, nego glagoljicom.'),
  ('language_literature-0011', 'Koji je irski pisac autor romana „Uliks”, čija se radnja odvija u Dublinu tijekom jednog dana?', 'James Joyce', array['Joyce']::text[], 'Taj dan, 16. lipnja, slavi se kao Bloomsday.'),
  ('music-0002', 'Koja je švedska grupa 1974. pobijedila na Euroviziji pjesmom „Waterloo”?', 'ABBA', '{}', 'Ime je sastavljeno od početnih slova imena članova: Agnetha, Björn, Benny i Anni-Frid.'),
  ('music-0003', 'Koja je zadarska grupa 1989. Jugoslaviji donijela jedinu pobjedu na Euroviziji?', 'Riva', '{}', 'Zbog te pobjede Eurovizija se 1990. održala u Zagrebu.'),
  ('music-0004', 'Koji je instrument oko 1700. u Firenci izumio Bartolomeo Cristofori?', 'Klavir', array['Glasovir', 'Pianoforte']::text[], 'U inventaru Medicija opisan je kao novi instrument koji svira i tiho i glasno, „il piano e il forte”.'),
  ('music-0005', 'Koji je skladatelj Devetu simfoniju napisao gotovo potpuno gluh?', 'Ludwig van Beethoven', array['Beethoven']::text[], 'Glazbu „Ode radosti” iz njezina završnog stavka Europske su zajednice 1985. usvojile kao himnu.'),
  ('music-0006', 'Koji je hrvatski skladatelj napisao operu „Nikola Šubić Zrinjski”?', 'Ivan Zajc', array['Zajc']::text[], 'Najpoznatiji dio opere je muški zbor „U boj”.'),
  ('music-0007', 'Koji je bend 1969. objavio album „Abbey Road”, nazvan po londonskoj ulici u kojoj je bio njihov studio?', 'The Beatles', array['Beatles', 'Beatlesi']::text[], 'Bio je to posljednji album koji su zajedno snimili, iako je „Let It Be” objavljen kasnije.'),
  ('music-0008', 'U kojem je američkom gradu rođen jazz trubač Louis Armstrong?', 'New Orleans', array['Nju Orleans']::text[], 'Nadimak Satchmo dolazi od riječi satchelmouth, otprilike „usta kao torba”.'),
  ('music-0009', 'Koji je oblik tradicionalnog višeglasnog pjevanja iz Dalmacije 2012. upisan na UNESCO-ov popis nematerijalne baštine?', 'Klapsko pjevanje', array['Klapa']::text[], 'Riječ klapa znači „družina prijatelja”, a pjeva se uglavnom bez pratnje instrumenata.'),
  ('music-0010', 'Koji je talijanski skladatelj napisao „Četiri godišnja doba”?', 'Antonio Vivaldi', array['Vivaldi']::text[], 'Bio je svećenik, a zbog crvene kose zvali su ga „crveni svećenik”.'),
  ('music-0011', 'Koje je Ravelovo djelo izgrađeno na ritmu malog bubnja koji se ponavlja kroz cijelu skladbu?', 'Bolero', array['Boléro']::text[], 'Naručila ga je plesačica Ida Rubinstein, a ritam se ponovi 169 puta.'),
  ('nature-0002', 'Koja je najveća životinja za koju znamo da je ikad živjela na Zemlji?', 'Plavetni kit', array['Plavi kit']::text[], 'Hrani se gotovo isključivo sitnim račićima, krilom.'),
  ('nature-0003', 'Kako se zove hladan i suh vjetar koji na mahove puše s kopna prema Jadranu?', 'Bura', '{}', 'Najjači izmjereni udar, 248 km/h, zabilježen je 1998. na Masleničkom mostu.'),
  ('nature-0004', 'Koji plin biljke upijaju iz zraka tijekom fotosinteze?', 'Ugljikov dioksid', array['CO2', 'Ugljični dioksid']::text[], 'Biljke su zelene jer klorofil ne upija zeleni dio svjetlosti, nego ga odbija.'),
  ('nature-0005', 'Koja je najbrža kopnena životinja?', 'Gepard', '{}', 'Za razliku od drugih mačaka, kandže može uvući samo djelomično.'),
  ('nature-0006', 'Koliko kostiju ima kostur odrasla čovjeka?', '206', '{}', 'Najmanja je stremen, jedna od slušnih koščica u srednjem uhu.'),
  ('nature-0007', 'Kako se u narodu zove proteus, slijepi vodozemac iz podzemnih voda dinarskog krša?', 'Čovječja ribica', '{}', 'Može doživjeti više od stotinu godina.'),
  ('nature-0008', 'Koji je najteži unutarnji organ ljudskog tijela?', 'Jetra', '{}', 'Iz samo četvrtine jetre može ponovno izrasti cijela.'),
  ('nature-0009', 'Koja se velika ptica strvinar gnijezdi na liticama otoka Cresa?', 'Bjeloglavi sup', array['Sup']::text[], 'Raspon krila može mu doseći i 2,8 metra.'),
  ('nature-0010', 'Koja je biljka, endem Velebita, bila prikazana na hrvatskoj kovanici od 50 lipa?', 'Velebitska degenija', array['Degenija']::text[], 'Ime je dobila po mađarskom prirodoslovcu Árpádu von Degenu, koji ju je pronašao 1907.'),
  ('nature-0011', 'Koja biljka iz prašuma jugoistočne Azije ima najveći pojedinačni cvijet na svijetu?', 'Raflezija', array['Rafflesia', 'Rafflesia arnoldii']::text[], 'Širi miris trulog mesa kojim privlači muhe oprašivače.'),
  ('science_tech-0002', 'Koji je izumitelj rođen u Smiljanu zaslužan za razvoj sustava izmjenične struje?', 'Nikola Tesla', array['Tesla']::text[], 'Po njemu je nazvana mjerna jedinica za magnetsku indukciju.'),
  ('science_tech-0003', 'Koji je kemijski simbol za zlato?', 'Au', '{}', 'Simbol dolazi od latinske riječi aurum.'),
  ('science_tech-0004', 'Koji je najveći planet Sunčeva sustava?', 'Jupiter', '{}', 'Masa mu je oko dva i pol puta veća od mase svih ostalih planeta zajedno.'),
  ('science_tech-0005', 'Tko je 12. travnja 1961. postao prvi čovjek u svemiru?', 'Jurij Gagarin', array['Gagarin', 'Yuri Gagarin']::text[], 'Let letjelicom Vostok 1 trajao je oko 108 minuta.'),
  ('science_tech-0006', 'Koji je zagrebački izumitelj 1906. patentirao prvu mehaničku olovku?', 'Slavoljub Penkala', array['Penkala', 'Eduard Slavoljub Penkala']::text[], 'Konstruirao je i avion kojim je 1910. poletio prvi hrvatski pilot Dragutin Novak.'),
  ('science_tech-0007', 'Tko je 1989. u CERN-u osmislio World Wide Web?', 'Tim Berners-Lee', array['Berners-Lee']::text[], 'Web je cijelom internetu postao dostupan u kolovozu 1991.'),
  ('science_tech-0008', 'Kako se zove niz brojeva u kojem je svaki broj zbroj dvaju prethodnih?', 'Fibonaccijev niz', array['Fibonacci', 'Fibonaccijevi brojevi']::text[], 'Fibonacci ga je 1202. opisao primjerom razmnožavanja zečeva.'),
  ('science_tech-0009', 'Kojeg plina ima najviše u Zemljinoj atmosferi?', 'Dušik', array['N2']::text[], 'Kisika u suhom zraku ima oko 21 %, a argona manje od 1 %.'),
  ('science_tech-0010', 'Koji je hrvatski kemičar 1975. dobio Nobelovu nagradu za istraživanja stereokemije?', 'Vladimir Prelog', array['Prelog']::text[], 'Nagradu je podijelio s australsko-britanskim kemičarom Johnom Cornforthom.'),
  ('science_tech-0011', 'Koji se planet Sunčeva sustava okreće gotovo na boku, s osi nagnutom za oko 98 stupnjeva?', 'Uran', array['Uranus']::text[], 'Zbog toga svaki pol ima oko 42 godine neprekidnog dana, a zatim 42 godine noći.'),
  ('sport-0002', 'Koji je sport dobio ime po engleskom imanju vojvode od Beauforta?', 'Badminton', '{}', 'Imanje Badminton House nalazi se u Gloucestershireu, gdje je igra postala popularna u 19. stoljeću.'),
  ('sport-0003', 'Koja japanska borilačka vještina u prijevodu znači „nježni put”?', 'Judo', array['Džudo']::text[], 'Ju znači nježno ili popustljivo, a do znači put.'),
  ('sport-0004', 'Koje boje kapicu nose vaterpolski vratari?', 'Crvenu', array['Crvena']::text[], 'Crvena kapica vratara propisana je pravilima, pa ga se lako razlikuje od ostalih igrača.'),
  ('sport-0005', 'Koju je tenisačicu 1993. u Hamburgu tijekom meča nožem napao opsesivni obožavatelj Steffi Graf?', 'Monika Seleš', array['Seleš', 'Monica Seles']::text[], 'Napad ju je udaljio s terena više od dvije godine.'),
  ('sport-0006', 'Na kojoj je stazi Niki Lauda 1976. doživio nesreću u kojoj je zadobio teške opekline?', 'Nürburgring', array['Nurburgring', 'Nordschleife']::text[], 'Na staze se vratio nakon samo šest tjedana.'),
  ('sport-0007', 'Koji je skakač s motkom čak 35 puta postavio svjetski rekord?', 'Sergej Bubka', array['Bubka', 'Serhij Bubka']::text[], 'Rekord je rušio 17 puta na otvorenom i 18 puta u dvorani.'),
  ('sport-0008', 'Koja je češka sportašica na Zimskim olimpijskim igrama 2018. osvojila zlato i u alpskom skijanju i u snowboardu?', 'Ester Ledecká', array['Ledecká', 'Ledecka']::text[], 'U skijanju je pobijedila u superveleslalomu, a u snowboardu u paralelnom veleslalomu.'),
  ('sport-0009', 'Po kojem je tenisaču nazvan središnji stadion Australian Opena u Melbourneu?', 'Rod Laver', array['Laver']::text[], 'Laver je jedini koji je dvaput osvojio kalendarski Grand Slam, 1962. i 1969.'),
  ('sport-0010', 'Kojim se nadimkom, po južnoafričkoj antilopi, zove ragbi reprezentacija Južne Afrike?', 'Springboksi', array['Springboks', 'Springbok']::text[], 'Kao domaćini osvojili su Svjetsko prvenstvo 1995., uz snažnu podršku Nelsona Mandele.'),
  ('sport-0011', 'Koji je biciklist 2020., s 21 godinom, osvojio Tour de France?', 'Tadej Pogačar', array['Pogačar', 'Pogacar']::text[], 'Tour je kasnije osvojio još nekoliko puta.'),
  ('sport-0012', 'Iz čega je vozač Formule 1 Daniel Ricciardo pio šampanjac na pobjedničkom postolju?', 'Iz cipele', array['Cipela', 'Tenisica']::text[], 'Ritual se zove „shoey” i potječe iz Australije.'),
  ('sport-0013', 'Koja je reprezentacija osvojila zlato u bejzbolu na Olimpijskim igrama u Tokiju?', 'Japan', '{}', 'Bejzbol se u Tokiju vratio u olimpijski program nakon pauze od 2008.'),
  ('sport-0014', 'Koju je reprezentaciju Hrvatska pobijedila 3:0 u četvrtfinalu Svjetskog prvenstva 1998.?', 'Njemačku', array['Njemačka']::text[], 'Golove su zabili Jarni, Vlaović i Šuker.'),
  ('sport-0015', 'Kolika je visina mreže u ženskoj odbojci, u centimetrima?', '224 cm', '{}', 'Kod muškaraca mreža je visoka 243 cm.'),
  ('sport-0016', 'Koliko kilometara iznosi biciklistička dionica Ironman triatlona?', '180 km', '{}', 'Prije bicikla pliva se 3,86 km, a nakon njega trči maraton od 42,195 km.'),
  ('sport-0017', 'Točno ili netočno: u golfu „eagle” znači da je rupa odigrana dva udarca ispod para.', 'Točno', '{}', 'Jedan udarac ispod para je birdie, a tri ispod albatros.'),
  ('sport-0018', 'Točno ili netočno: Kanada kao domaćin Ljetnih olimpijskih igara u Montrealu 1976. nije osvojila nijedno zlato.', 'Točno', '{}', 'Kanađani su na tim Igrama osvojili pet srebara i šest bronci.'),
  ('sport-0019', 'Koji je slavni francuski nogometaš zapalio olimpijski plamen na Zimskim olimpijskim igrama u Albertvilleu 1992.?', 'Michel Platini', array['Platini']::text[], 'Plamen je zapalio zajedno s jednim dječakom.'),
  ('sport-0020', 'Koji je trener s Monacom osvojio francusko prvenstvo 1988., a kasnije postao legenda Arsenala?', 'Arsène Wenger', array['Wenger']::text[], 'Arsenal je vodio punih 22 godine, od 1996. do 2018.'),
  ('sport-0021', 'Koju je reprezentaciju Hrvatska pobijedila rezultatom 3:2 na putu do oba naslova u Davis Cupu, 2005. i 2018.?', 'SAD', array['Sjedinjene Američke Države', 'Amerika']::text[], 'Polufinale 2018. igralo se u Zadru.'),
  ('sport-0022', 'Po kojem je nogometašu nazvana gradska zračna luka u Belfastu?', 'George Best', array['Best']::text[], 'Best je igrao za Manchester United i 1968. osvojio Zlatnu loptu.'),
  ('sport-0023', 'U kojem su stilu hrvanja dopušteni zahvati samo iznad pojasa?', 'Grčko-rimskom', array['Grčko-rimski']::text[], 'U slobodnom stilu smiju se hvatati i noge.'),
  ('sport-0024', 'Koji je boksač 1994., s 45 godina, postao najstariji svjetski prvak u teškoj kategoriji?', 'George Foreman', array['Foreman']::text[], 'Nokautirao je gotovo 19 godina mlađeg Michaela Moorera.'),
  ('sport-0025', 'Točno ili netočno: Saint-Étienne je francuski klub s najviše naslova državnog prvaka.', 'Netočno', '{}', 'Rekord drži PSG, koji je Saint-Étienne prestigao 2023.'),
  ('sport-0026', 'Koji je šahist bio svjetski prvak najdulje, punih 27 godina?', 'Emanuel Lasker', array['Lasker']::text[], 'Naslov je držao od 1894. do 1921.'),
  ('sport-0027', 'Koji je američki atletičar na 400 m s preponama od 1977. do 1987. ostao neporažen u 122 uzastopne utrke?', 'Edwin Moses', array['Moses']::text[], 'U tom je razdoblju osvojio i olimpijsko zlato u Los Angelesu 1984.'),
  ('sport-0028', 'Kako se zove NBA momčad iz Phoenixa?', 'Phoenix Suns', array['Suns']::text[], 'U NBA ligu ušli su 1968.'),
  ('nature-0012', 'Točno ili netočno: dalmatinac je ime dobio po Dalmaciji.', 'Točno', '{}', 'Štenci se rađaju potpuno bijeli, a prve točke dobivaju u desetak dana.'),
  ('geography-0012', 'Točno ili netočno: Kineski zid vidi se golim okom s Mjeseca.', 'Netočno', '{}', 'Dovoljno je dug, ali preuzak: s Mjeseca bi izgledao kao vlas kose gledana s tri kilometra.'),
  ('history-0012', 'Točno ili netočno: Napoleon Bonaparte bio je neobično nizak za svoje doba.', 'Netočno', '{}', 'Bio je visok oko 1,67 m, prosječno za ono doba; mit su širili britanski karikaturisti.'),
  ('science_tech-0012', 'Točno ili netočno: zvuk se kroz zrak širi brže nego kroz vodu.', 'Netočno', '{}', 'U vodi je oko 4,3 puta brži nego u zraku.'),
  ('music-0012', 'Točno ili netočno: Wolfgang Amadeus Mozart rođen je nakon smrti Johanna Sebastiana Bacha.', 'Točno', '{}', 'Bach je umro 1750., a Mozart je rođen 1756.; kao dijete u Londonu upoznao je Bachova sina Johanna Christiana.'),
  ('sport-0029', 'Točno ili netočno: pobjednici prvih modernih Olimpijskih igara, 1896. u Ateni, dobivali su srebrne medalje.', 'Točno', '{}', 'Drugoplasirani su dobivali bakrenu medalju, a trećeplasirani ništa.'),
  ('film_tv-0012', 'Točno ili netočno: Walt Disney osobno je posuđivao glas Mikiju Mausu u prvim crtićima.', 'Točno', '{}', 'Glas mu je davao do 1946., kad je ulogu preuzeo Jimmy MacDonald.'),
  ('language_literature-0012', 'Točno ili netočno: riječ „robot” prvi je put upotrijebljena u drami češkog pisca Karela Čapeka.', 'Točno', '{}', 'Riječ je predložio njegov brat Josef, prema češkoj riječi robota, prisilni rad.'),
  ('culture-0012', 'Točno ili netočno: Eiffelov toranj od početka je zamišljen kao trajna građevina.', 'Netočno', '{}', 'Trebao je biti srušen 1909., a spasila ga je korisnost za radiotelegrafiju.'),
  ('general-0012', 'Točno ili netočno: znak za pomoć SOS izvorno je kratica za „Save Our Souls”.', 'Netočno', '{}', 'Izabran je kao lako prepoznatljiv niz Morseovih znakova: tri točke, tri crte, tri točke.');
